// core: two-pass placement - latency ring first, resource fit second
const ring=T.nodes.filter(n=>n.rtt_ms<=6);const spill=T.nodes.filter(n=>n.rtt_ms>6);
const load={};const place={};
for(const tk of T.tasks){const pool=[...ring,...spill].filter(n=>(load[n.id]||0)+tk.cpu<=n.cpu);assert(pool.length>0,'fit');const n=pool[0];load[n.id]=(load[n.id]||0)+tk.cpu;place[tk.id]=n.id;}
const maxload=Math.max(...Object.values(load));const cap=Math.max(...T.nodes.map(n=>n.cpu));
J({place,utilization:load,max_util_pct:Math.round(100*maxload/cap)});assert(maxload<=cap,'capacity');

// end-to-end: node failure -> migrate its services to neighbors
const before={svc_a:'fog-1',svc_b:'fog-1',svc_c:'fog-2'};const failed='fog-1';
const live=T.nodes.filter(n=>n.id!==failed);const after={};let moved=0;
for(const [svc,node] of Object.entries(before)){if(node===failed){after[svc]=live[moved%live.length].id;moved++;}else after[svc]=node;}
J({failed,before,after,migrated:moved});assert(moved===2,'migrate');assert(!Object.values(after).includes(failed),'drained');
